insert into public.work_orders (id, sequential_number, title, description, category_id, location_id, priority, status, requester_id, lead_worker_id, contact_person, access_notes, expected_date, hold_reason, hold_details, next_action, hold_waiting_on, completion_summary, is_unrequested, created_at, updated_at, started_at, completed_at, closed_at, reopened_at) values
  ('b0000001-0000-4000-8000-000000000007', 1031, 'Cieknący kran w sali 104', 'Z kranu przy tablicy cały czas kapie woda, w zlewie stoi kałuża. Wykładowcy proszą o naprawę przed zajęciami.', '0c0c0c03-0000-4000-8000-000000000009', '0a0a0a02-0000-4000-8000-000000000002', 'BREAKDOWN', 'IN_PROGRESS', '11111111-0000-4000-8000-000000000003', '33333333-0000-4000-8000-000000000009', null, 'Klucz do zaplecza wod-kan w magazynie B-M1.', current_date + 1, null, null, null, null, null, false, now() - interval '2148 seconds', now() + interval '5652 seconds', now() - interval '48 seconds', null, null, null),
  ('b0000002-0000-4000-8000-000000000008', 1032, 'Uszkodzona klamka w drzwiach sali 212', 'Klamka luźna, drzwi trudno domknąć. Sale wynajmowane od 9:00, więc usterka przeszkadza w zajęciach.', '0c0c0c04-0000-4000-8000-000000000000', '0a0a0a03-0000-4000-8000-000000000003', 'URGENT', 'DONE', '11111111-0000-4000-8000-000000000003', '44444444-0000-4000-8000-000000000002', null, null, null, null, null, null, null, 'Wymieniona klamka na nową z zasobów magazynowych, regulacja zamka. Drzwi domykają się normalnie — sprawdzone.', false, now() - interval '69648 seconds', now() + interval '8652 seconds', now() + interval '5952 seconds', now() + interval '8652 seconds', null, null),
  ('b0000003-0000-4000-8000-000000000009', 1033, 'Przygotowanie auli na inaugurację roku', 'Ustawić 180 krzeseł w trzech rzędach, rozwiesić baner, sprawdzić mikrofony i projektor. Próba generalna dla służb o 16:00.', '0c0c0c06-0000-4000-8000-000000000002', '0a0a0a01-0000-4000-8000-000000000001', 'URGENT', 'ASSIGNED', '11111111-0000-4000-8000-000000000003', '44444444-0000-4000-8000-000000000002', 'Dziekanat, p. Ilona (wew. 214)', 'Wejście od strony podjazdu, klucze u portierni do 7:30.', current_date + 1, null, null, null, null, null, false, now() - interval '63648 seconds', now() - interval '61848 seconds', null, null, null, null),
  ('b0000004-0000-4000-8000-000000000000', 1034, 'Przeniesienie 12 krzeseł do sali 007', 'Potrzebne na zajęcia grupy porannej, decyzja podjęta na miejscu.', '0c0c0c07-0000-4000-8000-000000000003', '0a0a0a06-0000-4000-8000-000000000006', 'NORMAL', 'DONE', '44444444-0000-4000-8000-000000000002', '44444444-0000-4000-8000-000000000002', null, null, null, null, null, null, null, '12 krzeseł przeniesionych z auli do sali 007, ustawione wg wskazań prowadzącej zajęcia.', true, now() + interval '16752 seconds', now() + interval '16752 seconds', now() + interval '14352 seconds', now() + interval '16752 seconds', null, null),
  ('b0000005-0000-4000-8000-000000000001', 1035, 'Awaria oświetlenia na korytarzu I piętra', 'Nie działa ok. 2/3 świetlówek na korytarzu przy salach 101–110. Rano ciemno, studenci potykają się przy schodach.', '0c0c0c02-0000-4000-8000-000000000008', '0a0a0a04-0000-4000-8000-000000000004', 'BREAKDOWN', 'ON_HOLD', '11111111-0000-4000-8000-000000000003', '33333333-0000-4000-8000-000000000009', null, null, null, 'brak_materialow', 'Spalony zasilacz/sterownik oświetlenia, brak zamiennika w magazynie. Bezpiecznik wymieniony, nie pomógł.', 'Zamówić zasilacz LED 150 W (model jak w sali 104) i wrócić do zadania po dostawie.', '22222222-0000-4000-8000-000000000006', null, false, now() - interval '3048 seconds', now() + interval '2952 seconds', now() - interval '1848 seconds', null, null, null),
  ('b0000006-0000-4000-8000-000000000002', 1030, 'Naprawa zamka w pokoju 15 (sekretariat)', 'Zamek w drzwiach sekretariatu zacina się, trzeba mocno naciskać klamkę. Sekretariat pracuje od 7:30.', '0c0c0c04-0000-4000-8000-000000000000', '0a0a0a05-0000-4000-8000-000000000005', 'NORMAL', 'REOPENED', '11111111-0000-4000-8000-000000000003', '66666666-0000-4000-8000-000000000008', null, null, null, null, null, null, null, 'Wymieniona wkładka i wyregulowany zamknięcie — wykonane wczoraj, dziś zamek znowu pracuje źle.', false, now() - interval '171048 seconds', now() + interval '11052 seconds', now() - interval '85248 seconds', null, null, now() + interval '1152 seconds'),
  ('b0000007-0000-4000-8000-000000000003', 1036, 'Czujnik ruchu w WC przy auli nie reaguje', 'Światło nie gaśnie po wyjściu — czujnik świeci ciągle albo w ogóle nie wykrywa ruchu. Zgłasza sprzątanie.', '0c0c0c02-0000-4000-8000-000000000008', '0a0a0a09-0000-4000-8000-000000000009', 'NORMAL', 'NEW', '22222222-0000-4000-8000-000000000006', null, null, null, null, null, null, null, null, null, false, now() - interval '4248 seconds', now() - interval '4248 seconds', null, null, null, null),
  ('b0000008-0000-4000-8000-000000000004', 1037, 'Przegląd gaśnic w budynkach A i B', 'Kontrola ważności i plomb gaśnic. W razie braków — wpisać do materiału i zgłosić wymianę.', '0c0c0c09-0000-4000-8000-000000000005', '0a0a0a07-0000-4000-8000-000000000007', 'NORMAL', 'DONE', '11111111-0000-4000-8000-000000000003', '66666666-0000-4000-8000-000000000008', null, null, null, null, null, null, null, 'Sprawdzono 14 gaśnic. 12 OK, 2 z nieczytelną etykietą przeglądu — oznaczone do wymiany przez dostawcę.', false, now() - interval '3348 seconds', now() + interval '6552 seconds', now() + interval '2052 seconds', now() + interval '6552 seconds', null, null),
  ('b0000009-0000-4000-8000-000000000005', 1038, 'Zabezpieczenie luzującej się płytki w hallu', 'Odchodząca płytka gresowa przy wejściu głównym — ryzyko potknięcia.', '0c0c0c08-0000-4000-8000-000000000004', '0a0a0a07-0000-4000-8000-000000000007', 'NORMAL', 'DONE', '55555555-0000-4000-8000-000000000005', '55555555-0000-4000-8000-000000000005', null, null, null, null, null, null, null, 'Miejsce oznaczone taśmą i pachołkiem, zgłoszone do trwałej naprawy. Na razie bezpiecznie.', true, now() + interval '12552 seconds', now() + interval '12552 seconds', now() + interval '12252 seconds', now() + interval '12552 seconds', null, null)
