  ('e0000001-0000-4000-8000-000000000005', 'b0000001-0000-4000-8000-000000000007', 'STATUS', null, 'ASSIGNED', 'Do Mariusza, dziś rano. Zanim wejdzie ekipa sprzątająca.', null, '11111111-0000-4000-8000-000000000003', '11111111-0000-4000-8000-000000000003', now() - interval '1848 seconds', null, null),
  ('e0000002-0000-4000-8000-000000000006', 'b0000001-0000-4000-8000-000000000007', 'STATUS', 'ASSIGNED', 'IN_PROGRESS', 'Zaczynam. Rozebrana batería, widać zużytą uszczelkę.', null, '33333333-0000-4000-8000-000000000009', '33333333-0000-4000-8000-000000000009', now() - interval '48 seconds', null, null),
  ('e0000003-0000-4000-8000-000000000007', 'b0000001-0000-4000-8000-000000000007', 'COMMENT', null, null, 'Sterówka uszczelki rozmiar 3/4. Część jest w magazynie, składam z powrotem.', null, '33333333-0000-4000-8000-000000000009', '33333333-0000-4000-8000-000000000009', now() + interval '5652 seconds', null, null),
  ('e0000004-0000-4000-8000-000000000008', 'b0000002-0000-4000-8000-000000000008', 'STATUS', null, 'ASSIGNED', 'Tomasz ma wolne 15 minut po porannej obchodzie.', null, '22222222-0000-4000-8000-000000000006', '22222222-0000-4000-8000-000000000006', now() - interval '68448 seconds', null, null),
  ('e0000005-0000-4000-8000-000000000009', 'b0000002-0000-4000-8000-000000000008', 'STATUS', 'ASSIGNED', 'IN_PROGRESS', null, null, '44444444-0000-4000-8000-000000000002', '44444444-0000-4000-8000-000000000002', now() + interval '5952 seconds', null, null),
