  ('e0000007-0000-4000-8000-000000000001', 'b0000003-0000-4000-8000-000000000009', 'STATUS', null, 'ASSIGNED', 'Prowadzi Tomasz, pomaga Katarzyna. Do wykonania do jutra do 15:00.', null, '11111111-0000-4000-8000-000000000003', '11111111-0000-4000-8000-000000000003', now() - interval '61848 seconds', null, null),
  ('e0000008-0000-4000-8000-000000000002', 'b0000004-0000-4000-8000-000000000000', 'STATUS', null, 'DONE', 'Praca wykonana bez wcześniejszego zlecenia. Wykonawcy: Tomasz Zieliński.', null, '44444444-0000-4000-8000-000000000002', '44444444-0000-4000-8000-000000000002', now() + interval '16752 seconds', null, null),
  ('e0000009-0000-4000-8000-000000000003', 'b0000005-0000-4000-8000-000000000001', 'STATUS', null, 'ASSIGNED', null, null, '11111111-0000-4000-8000-000000000003', '11111111-0000-4000-8000-000000000003', now() - interval '2448 seconds', null, null),
  ('e000000a-0000-4000-8000-000000000004', 'b0000005-0000-4000-8000-000000000001', 'STATUS', 'ASSIGNED', 'IN_PROGRESS', 'Sprawdzam obwód i zasilacze.', null, '33333333-0000-4000-8000-000000000009', '33333333-0000-4000-8000-000000000009', now() - interval '1848 seconds', null, null),
  ('e000000b-0000-4000-8000-000000000005', 'b0000005-0000-4000-8000-000000000001', 'STATUS', 'IN_PROGRESS', 'ON_HOLD', 'Powód: brak części. Nastepny krok: zamówić zasilacz 150 W. Korytarz tymczasowo doświetlony lampą budowlaną.', 'Kierownik zamawia zasilacz LED 150 W.', '33333333-0000-4000-8000-000000000009', '33333333-0000-4000-8000-000000000009', now() + interval '2952 seconds', null, null),
  ('e000000c-0000-4000-8000-000000000006', 'b0000006-0000-4000-8000-000000000002', 'STATUS', null, 'ASSIGNED', 'Marek — jak będzie przy budynku B.', null, '22222222-0000-4000-8000-000000000006', '22222222-0000-4000-8000-000000000006', now() - interval '170748 seconds', null, null),
  ('e000000d-0000-4000-8000-000000000007', 'b0000006-0000-4000-8000-000000000002', 'STATUS', 'ASSIGNED', 'DONE', 'Wymieniona wkładka zamka, wyregulowane domknięcie. Działa.', null, '66666666-0000-4000-8000-000000000008', '22222222-0000-4000-8000-000000000006', now() - interval '74448 seconds', null, null),
  ('e000000e-0000-4000-8000-000000000008', 'b0000006-0000-4000-8000-000000000002', 'STATUS', 'DONE', 'CLOSED', 'Zamknięte po akceptacji.', null, '11111111-0000-4000-8000-000000000003', '11111111-0000-4000-8000-000000000003', now() - interval '72048 seconds', null, null),
  ('e000000f-0000-4000-8000-000000000009', 'b0000006-0000-4000-8000-000000000002', 'STATUS', 'CLOSED', 'REOPENED', 'Sekretariat zgłasza, że zamek znowu zacina — prawdopodobnie spasowanie klamki. Wracamy do tematu.', null, '11111111-0000-4000-8000-000000000003', '11111111-0000-4000-8000-000000000003', now() + interval '1152 seconds', null, null),
  ('e0000010-0000-4000-8000-000000000000', 'b0000006-0000-4000-8000-000000000002', 'NOTE', null, null, 'Marek sprawdził rano: wkładka luźna w korpusie, dociśnięcie klamki pomaga. Zamówiona nowa klamka z wkładką.', 'Montaż nowej klamki po dostawie (jutro rano).', '66666666-0000-4000-8000-000000000008', '22222222-0000-4000-8000-000000000006', now() + interval '11052 seconds', null, null),
  ('e0000011-0000-4000-8000-000000000001', 'b0000008-0000-4000-8000-000000000004', 'STATUS', 'ASSIGNED', 'DONE', 'Marek zgłosił przez telefon na wspólnym komputerze: 12 OK, 2 do wymiany.', null, '66666666-0000-4000-8000-000000000008', '22222222-0000-4000-8000-000000000006', now() + interval '6552 seconds', null, null),
